def editorSums(ops):
    left = []
    right = []
    out = []
    for t, x in ops:
        if t == 0:
            left.append(x)
        elif t == 1:
            m = min(x, len(left))
            if m:
                del left[len(left) - m:]
            out.append(m)
        elif t == 2:
            m = min(x, len(left))
            if m:
                moved = left[len(left) - m:]
                del left[len(left) - m:]
                moved.reverse()
                right.extend(moved)
            out.append(sum(left[-10:]))
        else:
            m = min(x, len(right))
            if m:
                moved = right[len(right) - m:]
                del right[len(right) - m:]
                moved.reverse()
                left.extend(moved)
            out.append(sum(left[-10:]))
    return out
